#define SYS_close_range 436

#define CLOSE_RANGE_CLOEXEC (1U << 0)
#define CLOSE_RANGE_UNSHARE (1U << 1)

// 1. Simple closure of FDs 3 through 9 (inclusive)
unsigned int first = 3;
unsigned int last = 9;
int status = syscall(SYS_close_range, first, last, 0);

// 2. Setting Close-on-Exec for FDs 10 to 19
syscall(SYS_close_range, 10U, 19U, CLOSE_RANGE_CLOEXEC);

// 3. Closure combined with unsharing
syscall(SYS_close_range, 20U, 30U,
        CLOSE_RANGE_CLOEXEC | CLOSE_RANGE_UNSHARE);
